clc;
close all;
clear all;
T=2*pi;
omega=2*pi/T;
t=linspace(0,4*pi,1000);
N=1000;  % harmonics
sq_wave= zeros(size(t));
for n=1:2:N

 sq_wave=sq_wave +4/(n*pi)*sin(n*omega*t);
end
figure(); %[output:2e5a4483]
plot(t,sq_wave); %[output:2e5a4483]
grid on; %[output:2e5a4483]

